#!/usr/bin/env python3
"""gen_aud_gain.py -- the audio attenuation table (interface 0.5, program word 34's ATTEN;
docs/architecture.md "Audio (Phase 4)"): ATTEN n is -0.5 n dB, 255 mute. The gain is
Q1.15: gain(0) = 32768 is exactly unity ((s * 32768) >> 15 == s), so a program that never
touches the volume gets its samples bit-exact.

    gen_aud_gain.py            write h264/aud_gain.sv
    gen_aud_gain.py --check    exit 1 if it differs from the table
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(ROOT, "h264", "aud_gain.sv")


def gain(n):
    return 0 if n == 255 else int(round(32768 * 10 ** (-n / 40.0)))


def text():
    o = ["// h264/aud_gain.sv -- the audio attenuation table (generated by tools/gen_aud_gain.py --",
         "// edit the generator, never this file). ATTEN n (program word 34 [15:8], interface 0.5) is",
         "// -0.5 n dB, 255 mute; the gain is Q1.15, 0 exactly unity. A registered ROM: one case, one",
         "// output register (a ROM Quartus maps as it likes; 256 x 16).",
         "", "`default_nettype none", "",
         "module aud_gain (",
         "    input  wire        clk,",
         "    input  wire  [7:0] atten,",
         "    output logic [15:0] gain",
         ");",
         "    always_ff @(posedge clk) begin",
         "        case (atten)"]
    for n in range(256):
        o.append("            8'd%d: gain <= 16'd%d;" % (n, gain(n)))
    o += ["            default: gain <= 16'd0;", "        endcase", "    end", "endmodule", "",
          "`default_nettype wire", ""]
    return "\n".join(o)


def main(argv):
    t = text()
    if "--check" in argv:
        old = open(OUT).read() if os.path.exists(OUT) else None
        if old != t:
            print("gen_aud_gain: h264/aud_gain.sv differs from the table (run tools/gen_aud_gain.py)")
            return 1
        print("gen_aud_gain: h264/aud_gain.sv matches")
        return 0
    with open(OUT, "w") as f:
        f.write(t)
    print("wrote h264/aud_gain.sv")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
